#nullable enable
using Marten;
using Spend.Contracts;
using Wolverine.Http;
using Wolverine.Marten;

namespace Spend.Slices.Spend;

/// <summary>
/// Opens a project inside a department. THE CREATE SLICE, so it starts the stream rather than fetching
/// one: <c>terminal="projectId:generated"</c> on the model says the id is minted by the handler, which
/// means the stream cannot exist yet and asking for it would be asking for the thing being made.
/// </summary>
public static class OpenProjectEndpoint
{
    public const string Route = "/projects";

    /// <summary>The minted id is the response body, and that is not cosmetic — a journey test must use the
    /// id the API handed back rather than one it made up, or it cannot see a slice that echoes something
    /// subtly different.</summary>
    public sealed record Opened(Guid ProjectId);

    [WolverinePost(Route)]
    public static (Opened, IStartStream) Open(OpenProject command)
    {
        var projectId = Guid.NewGuid();
        var opened = new ProjectOpened(projectId, command.DepartmentId, command.Name);

        return (new Opened(projectId), MartenOps.StartStream<OpenProjectState>(projectId, opened));
    }
}
